function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 4 || nums.length > 10000 || nums.length % 2 !== 0) return 'nums needs an even length from 4 to 10000.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each value is a whole number from 0 to 10^4.';
  const n = nums.length / 2;
  const counts = new Map();
  for (const v of nums) counts.set(v, (counts.get(v) ?? 0) + 1);
  if (counts.size !== n + 1 || ![...counts.values()].includes(n)) return 'One value must appear exactly n times and the other n values once each.';
  return null;
}

