function generate(rand, size) {
  const n = size === 'large' ? 1000 : 2 + Math.floor(rand() * 5);
  const limit = size === 'small' && rand() < 0.5 ? 20 : 10001;
  const used = new Set();
  // Distinct values from 0..limit-1; on a repeat, step to the next free value.
  const pick = () => {
    let value = Math.floor(rand() * limit);
    while (used.has(value)) value = (value + 1) % limit;
    used.add(value);
    return value;
  };
  const repeated = pick();
  const nums = new Array(n).fill(repeated);
  for (let i = 0; i < n; i++) nums.push(pick());
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
